package config

import (
	"crypto/rand"
	"fmt"
	"slices"
	"strings"

	"github.com/mhagnumdw/dwnvr/internal/area"
)

// Area is an area drawn over the camera's image, with the name the person
// gave it. The polygon and the rules belong to the area package; here is what
// the camera config stores.
type Area struct {
	// ID is short and generated by the server when the area arrives without
	// one. The Detections link and the alert point to it, and renaming the area
	// breaks neither.
	ID   string `json:"id"`
	Name string `json:"name"`

	// Rule is `touch` or `foot`. Absent, it's area.DefaultRule.
	Rule   string       `json:"rule,omitempty"`
	Points []area.Point `json:"points"`
}

// areaIDLen is 6 letters and digits: 36^6 is ~2 billion, and it only needs to
// not repeat within a camera, with at most area.MaxAreasPerCamera.
const areaIDLen = 6

const areaIDAlphabet = "abcdefghijklmnopqrstuvwxyz0123456789"

// WithAreaIDs returns the camera with an ID on each area that arrived without
// one. It doesn't touch an existing ID, not even a repeated one: CheckCamera
// is what checks, and an area must not change its ID behind anyone's back.
func (cam Camera) WithAreaIDs() Camera {
	if !slices.ContainsFunc(cam.Areas, func(a Area) bool { return a.ID == "" }) {
		return cam
	}
	used := make(map[string]bool, len(cam.Areas))
	for _, a := range cam.Areas {
		used[a.ID] = true
	}
	withIDs := slices.Clone(cam.Areas)
	for i := range withIDs {
		if withIDs[i].ID != "" {
			continue
		}
		for {
			id := newAreaID()
			if !used[id] {
				used[id] = true
				withIDs[i].ID = id
				break
			}
		}
	}
	cam.Areas = withIDs
	return cam
}

func newAreaID() string {
	b := make([]byte, areaIDLen)
	if _, err := rand.Read(b); err != nil {
		// crypto/rand only fails if the system has no entropy, and then
		// nothing else in dwnvr works either (the session uses the same).
		panic(fmt.Errorf("no randomness for the area ID: %w", err))
	}
	for i, v := range b {
		b[i] = areaIDAlphabet[int(v)%len(areaIDAlphabet)]
	}
	return string(b)
}

// checkAreas returns only the valid areas and one Warning per area removed.
// The first one with a name, or an ID, stands; a repeated one goes.
func checkAreas(cam Camera, av *[]Warning) []Area {
	if len(cam.Areas) == 0 {
		return cam.Areas
	}
	kept := make([]Area, 0, len(cam.Areas))
	names := map[string]bool{}
	ids := map[string]bool{}
	reject := func(i int, a Area, accepted string) {
		*av = append(*av, Warning{Camera: cam.ID, Field: fmt.Sprintf("areas[%d]", i),
			Value: fmt.Sprintf("%q", a.Name), Accepted: accepted, InEffect: "a área fica de fora"})
	}
	for i, a := range cam.Areas {
		name := strings.ToLower(strings.TrimSpace(a.Name))
		_, errRule := area.NewRule(a.Rule)
		_, errPoints := area.New(a.Points)
		switch {
		case len(kept) >= area.MaxAreasPerCamera:
			reject(i, a, fmt.Sprintf("até %d áreas por câmera", area.MaxAreasPerCamera))
		case name == "":
			reject(i, a, "um nome, que não fique vazio")
		case names[name]:
			reject(i, a, "um nome que não se repita na câmera")
		case !validAreaID(a.ID):
			reject(i, a, fmt.Sprintf("um id de 1 a %d letras minúsculas e dígitos", maxAreaIDLen))
		case ids[a.ID]:
			reject(i, a, "um id que não se repita na câmera")
		case errRule != nil:
			reject(i, a, "a regra "+acceptedRules())
		case errPoints != nil:
			reject(i, a, fmt.Sprintf("de %d a %d pontos, com as coordenadas de 0 a 1",
				area.MinAreaPoints, area.MaxAreaPoints))
		default:
			names[name] = true
			ids[a.ID] = true
			kept = append(kept, a)
		}
	}
	return kept
}

// maxAreaIDLen leaves room for an id written by hand in cameras.json; a
// generated one has areaIDLen.
const maxAreaIDLen = 16

// validAreaID accepts what fits unescaped in the Detections URL
// (`areas=<cam>/<id>`): only lowercase letters and digits.
func validAreaID(id string) bool {
	if id == "" || len(id) > maxAreaIDLen {
		return false
	}
	return strings.Trim(id, areaIDAlphabet) == ""
}

func acceptedRules() string {
	names := make([]string, 0, len(area.Rules))
	for n := range area.Rules {
		names = append(names, n)
	}
	slices.Sort(names)
	return strings.Join(names, " ou ")
}
